var n=`0367-cheese-fondue`;var t=`world-0367`;var r=`CH`;var s=`western-europe`;var a=4;var o=22;var g={en:`Cheese Fondue`,ua:`Сирне фондю`};var l={en:`A traditional Switzerland dish made with garlic, lemon juice, gruyère, emmental. This home-style preparation follows its characteristic cooking method and uses measured ingredients.`,ua:`Традиційна страва кухні країни Швейцарія. Основні інгредієнти: часник, лимонний сік, грюєр, емменталь. Домашній варіант із характерною технологією та поетапно розподіленими продуктами.`};var d=[{en:`Wash and prepare the listed produce; dice or chop evenly for a consistent texture.`,ua:`Вимийте й підготуйте зазначені продукти; наріжте рівномірними кубиками або дрібними шматочками.`,t:[`chopping`,`dicing`],m:5,i:[[`garlic`,2,`clove`]]},{en:`Cook the listed ingredients in simmering water for about 6 minutes until tender; drain well if necessary.`,ua:`Варіть зазначені складники у воді приблизно 6 хвилин до м’якості; за потреби добре злийте воду.`,t:[`boiling`],m:6,i:[[`dry-white-wine`,340,`ml`],[`lemon-juice`,15,`ml`]]},{en:`Toss grated cheeses with starch and melt gradually into hot wine, stirring in a figure-eight motion until glossy and smooth; never let it boil hard.`,ua:`Змішайте терті сири з крохмалем і поступово розплавте в гарячому вині, помішуючи вісімкою до гладкості й блиску; не допускайте сильного кипіння.`,t:[`mixing`],m:9,i:[[`gruyere`,390,`g`],[`emmental`,340,`g`],[`cornstarch`,27,`g`],[`ground-nutmeg`,3,`g`]]},{en:`Finish with the listed ingredients, check seasoning and serve immediately.`,ua:`Додайте завершальні складники, перевірте смак і відразу подавайте.`,t:[`seasoning`,`garnishing`],m:2,i:[[`baguette`,520,`g`]]}];var u={slug:n,id:t,country:`CH`,region:s,servings:4,minutes:22,title:g,text:l,steps:d};export{r as country,u as default,t as id,o as minutes,s as region,a as servings,n as slug,d as steps,l as text,g as title};